	public static String decrypt(byte[] key, byte[] input) {

		try {
			Security.addProvider(new BouncyCastleProvider());

			SecretKeyFactory keyFactory = SecretKeyFactory.getInstance("TripleDES");
			SecretKey theKey = keyFactory.generateSecret(new DESedeKeySpec(key));

			Cipher cipher = Cipher.getInstance(TRIPLE_DES_TRANSFORMATION_ENC, BOUNCY_CASTLE_PROVIDER);

			int blockSize = cipher.getBlockSize();

			// ✅ Extract IV
			byte[] iv = Arrays.copyOfRange(input, 0, blockSize);
			byte[] cipherText = Arrays.copyOfRange(input, blockSize, input.length);

			IvParameterSpec ivSpec = new IvParameterSpec(iv);
			cipher.init(Cipher.DECRYPT_MODE, theKey, ivSpec);

			byte[] decrypted = cipher.doFinal(cipherText);
			return new String(decrypted, StandardCharsets.UTF_8);

		} catch (Exception e) {
			logger.error("Decryption failed", e);
			return null;
		}
	}

	public static byte[] encode(byte[] input, byte[] key) throws Exception {

		Security.addProvider(new BouncyCastleProvider());

		SecretKeyFactory keyFactory = SecretKeyFactory.getInstance("TripleDES");
		SecretKey theKey = keyFactory.generateSecret(new DESedeKeySpec(key));

		Cipher cipher = Cipher.getInstance(TRIPLE_DES_TRANSFORMATION_ENC, BOUNCY_CASTLE_PROVIDER);

		// ✅ Secure random IV
		byte[] iv = new byte[cipher.getBlockSize()];
		SecureRandom secureRandom = new SecureRandom();
		secureRandom.nextBytes(iv);

		IvParameterSpec ivSpec = new IvParameterSpec(iv);
		cipher.init(Cipher.ENCRYPT_MODE, theKey, ivSpec);

		byte[] cipherText = cipher.doFinal(input);

		// ✅ Prepend IV to ciphertext (needed for decryption)
		ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
		outputStream.write(iv);
		outputStream.write(cipherText);

		return outputStream.toByteArray();
	}

